WITH pgrst_source AS ( SELECT "public"."question_options"."id", "public"."question_options"."question_id", "public"."question_options"."content", "public"."question_options"."label", "public"."question_options"."is_correct", "public"."question_options"."order_index", "public"."question_options"."removed_at" FROM "public"."question_options" WHERE  "public"."question_options"."question_id" = 'f3070000-0000-4000-8000-000000000001'   LIMIT '1000' OFFSET '0' )  SELECT null::bigint AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t;
